WITH RECURSIVE fl138_violation(c0,c1) AS NOT MATERIALIZED (SELECT DISTINCT t1.c1 AS c0, t1.c2 AS c1 FROM main.fl138_violation_at t1), fl139_violation(c0,c1) AS NOT MATERIALIZED (SELECT DISTINCT t1.c1 AS c0, t1.c2 AS c1 FROM main.fl139_violation_at t1), fl140_violation(c0,c1) AS NOT MATERIALIZED (SELECT DISTINCT t1.c1 AS c0, t1.c2 AS c1 FROM main.fl140_violation_at t1), fl141_violation(c0,c1) AS NOT MATERIALIZED (SELECT DISTINCT t1.c1 AS c0, t1.c2 AS c1 FROM main.fl141_violation_at t1), rr_diagnostic(c0) AS NOT MATERIALIZED (SELECT DISTINCT t1.c1 AS c0 FROM main.rr_diagnostic_at t1), s_rr_scope_drop(c0) AS MATERIALIZED (SELECT DISTINCT t1.c1 AS c0 FROM main.s_rr_scope_drop_at t1), violation(c0,c1,c2,c3,c4) AS NOT MATERIALIZED (SELECT DISTINCT 437 AS c0, 20 AS c1, 20 AS c2, t1.c0 AS c3, t1.c1 AS c4 FROM fl138_violation t1 WHERE NOT EXISTS (SELECT 1 FROM s_rr_scope_drop t2 WHERE (t2.c0 = t1.c0)) UNION SELECT DISTINCT 438 AS c0, 21 AS c1, 21 AS c2, t1.c0 AS c3, t1.c1 AS c4 FROM fl139_violation t1 WHERE NOT EXISTS (SELECT 1 FROM s_rr_scope_drop t2 WHERE (t2.c0 = t1.c0)) UNION SELECT DISTINCT 439 AS c0, 22 AS c1, 22 AS c2, t1.c0 AS c3, t1.c1 AS c4 FROM fl140_violation t1 WHERE NOT EXISTS (SELECT 1 FROM s_rr_scope_drop t2 WHERE (t2.c0 = t1.c0)) UNION SELECT DISTINCT 440 AS c0, 23 AS c1, 23 AS c2, t1.c0 AS c3, t1.c1 AS c4 FROM fl141_violation t1 WHERE NOT EXISTS (SELECT 1 FROM s_rr_scope_drop t2 WHERE (t2.c0 = t1.c0))) SELECT 0 AS __output,c0,NULL,NULL,NULL,NULL FROM rr_diagnostic UNION ALL SELECT 1 AS __output,c0,c1,c2,c3,c4 FROM violation
